-- One self-contained record following DocumentIngestSchema.
CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  "originalTitle" TEXT,
  "documentType" TEXT NOT NULL CHECK ("documentType" IN ('constitution','act','regulation','schedule_only')),
  "yearBs" NUMERIC NOT NULL,
  "yearAd" NUMERIC NOT NULL,
  "totalPages" INTEGER NOT NULL CHECK ("totalPages" >= 0),
  nodes JSONB NOT NULL
);

INSERT INTO legal_documents (id,title,"originalTitle","documentType","yearBs","yearAd","totalPages",nodes) VALUES ($CODEx05eaba9c2e49$doc_partnership_act_2020_1964__2020_partnership-act-2020_pdf$CODEx05eaba9c2e49$,$CODEx01a5f527bbdd$Partnership Act, 2020 (1964)$CODEx01a5f527bbdd$,NULL,$CODEx76f3b5a7170a$act$CODEx76f3b5a7170a$,2020,1964,22,$CODExb1756b2b5a97$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "www.lawcommission.gov.np \n1 \nwww.lawcommission.gov.np \nPartnership Act, 2020 (1964) \nDate of Authentication and Publication   \n2020-11-16 (28 Feb. 1964) \nAmendments", "children": []}, {"tier": 1, "nodeType": "section_group", "identifier": "Sections", "title": "Sections", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Judicial Administration Reform (Fourth", "content": "Amendment) Act, 2043 (1986)   2043-7-24 (9 Nov. 198 6)", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Partnership (First Amendment) Act, 2044 (1987)  2044-7-11 (28 Oct. 1987)", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "3", "title": "Administration of Justice Act, 2048 (1991) 2048- 2-16 (30 May 1991)", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Republic Strengthening and Some Nepal Laws", "content": "Amendment Act, 2066 (2010) 1  2066-10-7 (21 Jan 2010) \n \nAct Number 36 of the Year 2020 (1964) \nAn Act made to provide for provisions on partnership  \n \nPreamble : Whereas it is expedient to provide for legal provis ions on partnership \nfor the interest and convenience of general public;  \nNow, therefore be it enacted by His Majesty the Kin g Mahendra Bir \nBikram Shah Dev on the advice and with the consent of the Rastriya Panchayat.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-1", "title": "Chapter-1", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Short Title, Extent and Commencement : (1) This Act may be called", "content": "\"Partnership Act, 2020 (1964)\".  \n(2) This Act shall be extended throughout Nepal.  \n(3) This Act shall come into force immediately.  \n \n                                                             \n1  This Act came into force on 15 Jestha  2065 and \"Prasasti\" and the word \"Kingdom\" has been deleted.  \nwww.lawcommission.gov.np \n2 \nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Definition :  Unless the subject or context otherwise requires; in this Act;", "content": "(a)  \"Business\" includes industry, commerce (trade)  profession or \noccupation ( Briti).  \n(b)  \"Prescribed\" or \"as prescribed\" means prescrib ed or as prescribed in \nthis Act or Rules framed hereunder.  \n(c)  \"Third Party’ ( Unau bayakti ) means any other person other than \npartners in the partnership firm.  \n(d)  \"Notification\" means an order published in the  Nepal Gazette by the \nGovernment of Nepal.  \n2(f) \"Concerned Department\" means Department of Comm erce for \ncommercial matter, Department of Cottage and Rural Industry for \nthe matter related to cottage and rural industry an d Department of \nIndustry for any other industry.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "3", "title": "Definition of partnership : (1) Any business registered in a record of the", "content": "Government of Nepal by the persons who have agreed to share the profit of \nthe business carried on by them in a single name un der an agreement \n(Kabuliat ) made with each other which entitles all partners to take part in \nall business for each partner or entitles any of th em for the same on  behalf \nof all others.  \n(2) Persons who have entered into an agreement of p artnership shall \nbe called \"partners\" in relation to each partner an d shall be called \"firm\" in \na collective form and the name under which their bu siness in carried on is \ncalled the “name of firm\".  \n(3) No partnership firm shall be a person except partners.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Business carried on by joint family shall not be pa rtnership : If", "content": "coparceners of a joint family carry on joint busine ss without entering in to \n                                                             \n2  Amended by  Partnership (First Amendment) Act, 20 44. \nwww.lawcommission.gov.np \n3 \nwww.lawcommission.gov.np \nan agreement, the joint business of such family sha ll not be deemed \npartnership for the purpose of this Act.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -2", "title": "Chapter -2", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "5", "title": "Firm to be registered in the record of the concerne d Department :", "content": "A firm shall have to be registered in the record of  the concerned \nDepartment within a period of Six months from the d ate when the partners \nenter in to the agreement of partnership pursuant to this Act;    \nProvided that, any act or business carried on by the partnership or for \nthe partnership which is not registered pursuant to  this Section shall not get \nlegal validity pursuant to this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Matters to be set out in an application for  the re gistration of a", "content": "firm and fees for registration : In order to register a firm an application \nin the format as referred to in Schedule -1(a)  sha ll be submitted before the \nconcerned Department, stating the details as follow s, along with the fees as \nprescribed in Schedule- 2(a) and a copy of the agre ement concluded \nbetween partners, if any,                                                 \n(a) Full Name of the firm \n(b) The Principal place of business of the firm, \n(c) The objectives of the firm including the short description of the \nnature of the goods or services, as the case may be , which the firm \nintends to run the business,  \n(d)  The full name, surname and permanent address o f the partners, \n(e)  The matter of restriction imposed on the power  of a partner, if any,  \n(f)  The types of partnership and the capital subsc ribed by each partner, \n(g)  The name of a partner or partners, who represe nt the firm,  \n(h)  The mode to share the profit and loss between /among partners,  \nwww.lawcommission.gov.np \n4 \nwww.lawcommission.gov.np \n(i)   The mode to calculate the profit of a firm.  \n(j)  Any other matters prescribed by the concerned Department stating \nwhich should be set out in the application.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "7", "title": "Name of the Firm :  A Firm shall not be given such name which", "content": "resembles the name of any other firm which is alrea dy registered, or the \nname of any limited company which is already regist ered under Company \nAct.  \n8 Issuance of a Certificate after registration of a f irm :  If a firm  \nfulfils the conditions as referred to in Sections 6  and 7, the concerned \nDepartment shall register such firm pursuant to thi s Act and after \ncompleting registration the said Department shall i ssue a certificate ( Nissa ) \nof registration in the format as referred to in sch edule 3-(a) in the name of \npartners.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "9", "title": "No need to register previous firm : It shall not be required to register the", "content": "firm under this Act which has been already register ed pursuant to Private \nFirm Registration Act, 2014. Provided that, in case  any particulars as \nreferred to in Section 6 was not mentioned in  earl ier registration, the \nconcerned Department may seek such particulars and the partners shall \nsubmit such particulars to the concerned Department.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "310", "title": "Approval required to change the particulars : If it requires to make", "content": "any change in the particulars of application and in  the agreement submitted \npursuant to Section 6, an application shall be subm itted before the \nconcerned Department for this purpose and such chan ges may only be \nmade after the approval of the concerned Department.  \n411 Renewal : An application shall be submitted before the conc erned \nDepartment in the format as prescribed in Schedule 1(b) along with the \n                                                             \n3  Amended by First Amendment. \n4  Inserted by First Amendment. \nwww.lawcommission.gov.np \n5 \nwww.lawcommission.gov.np \nprescribed fee as referred to in Schedule-2(b) for the renewal of a firm \nregistered under this Act within a period of Thirty  Five days of the expiry \nof fiscal year of the firm. If an application is su bmitted within such period, \nthe concerned Department shall renew the firm and m ention the fact of \nrenewal in the registration inventory and the certi ficate of registration. No \nfirm shall carry on any business by the same name w ithout causing to effect \nrenewal.  \n511A. Concerned Department may seek particulars : (1) The concerned \nDepartment may seek particulars of accounts from the firm registered under \nthis Act.  \n(2) It shall be the duty of such firm to submit the  particulars of \naccounts sought pursuant to Sub-section (1) to the concerned Department.  \n611B. Power to cancel registration : (1) The concerned Department may cancel \nregistration of a firm which is registered under th is Act in the following \nconditions;  \n(a) If a firm registered for commercial business fails to \ncause to effect renewal of the firm within stipulat ed \ntime. \n(b) If the partners submit an application to terminate the \nregistration of the firm upon setting out reasonabl e \nreasons thereof to the concerned Department.  \n(c)  If a firm fails to submit the particulars sought b y the \nconcerned Department pursuant to Section 11a within  \nprescribed period.  \n(d)  If an industry related firm closes down the operat ing \nindustry, whether by providing notice thereof to th e \nconcerned Department or not.  \n                                                             \n5 Inserted by First Amendment. \n6  Inserted by First Amendment. \nwww.lawcommission.gov.np \n6 \nwww.lawcommission.gov.np \n(e)    If an industry related firm fails to cause t o effect the \nrenewal of the firm within the prescribed time from the \nexpiry of validity period to renew the firm; or fai ls to \nsubmit the written progress report on the action as  may \nbe required to be taken for the construction of fac tory, \npurchase of machinery or tools or equipment and \noperation of the industry in order to establish and  \noperate the industry as per the condition of the li cense \ndespite the firm has been renewed.  \n(f)    If a firm commits an act in contravention of  this Act or \nRules framed hereunder.  \n(2) The concerned Department shall give a reasonabl e opportunity to \nthe concerned firm to submit it's clarification bef ore canceling the \nregistration of that firm pursuant to Clauses (a), (c) (d) (e) or (f) of Sub-\nsection 1.  \n(3) If the concerned Department cancels the registr ation of a firm \npursuant to Clauses (a), (c), (d) (e) or (f) of Sub -section (1), no any other \nfirm which carries the same objectives shall be reg istered in the name of \nsuch partners of that firm for a period of one year", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter - 3", "title": "Chapter - 3", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "12", "title": "Mutual relation of partners : (1) The mutual rights and duties of the", "content": "partners in partnership firm shall be determined by  an agreement made \nbetween the partners. Such agreement may be in an e xpress form or may be \nimplied in the course of mutual dealing.                           \nwww.lawcommission.gov.np \n7 \nwww.lawcommission.gov.np \n(2) The agreement of partnership, if any, governs t he provisions of \npartnership and in a condition where there is no su ch agreement; the \nSections from 13 to 26 shall be applied to the partnership.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "13", "title": "Assets of partnership : The entire assets of the partnership shall be as", "content": "follows;  \n(a)  The all assets originally brought in to the st ock of the firm, \n(b)  Assets acquired by or for the firm or for the purpose or in the course \nof business of partnership,  \n(c)  Property earned by the firm in the course of b usiness; and  \n(d)  Good will of the business carried on by the pa rtnership.  \nExplanation : Except otherwise provided by the context, all \nproperty and rights and interest in property acquir ed with money \nbelonging to the firm shall be deemed to have been acquired for the \nfirm.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "14", "title": "Use of property of the partnership : No Partners shall use or cause to", "content": "use the property of the partnership firm for any ot her purpose other than the \npurpose of the partnership business.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "15", "title": "No compulsion for additional capital : No partner shall be compelled to", "content": "add more capital than the amount prescribed in the agreement of \npartnership deed despite the request of other partners.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "16", "title": "No substitution of partners : No partner shall, without the consent of all", "content": "other partners, make or keep to any other person as  a partner in the firm \ninstead of him/her.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "17", "title": "Every partner may participate in the business : (1) Except a partner", "content": "who is prohibited to take part in the management  of partnership pursuant to \nwww.lawcommission.gov.np \n8 \nwww.lawcommission.gov.np \nthe agreement, every partner shall be entitled to p articipate in the \nmanagement of  the business of the firm unless other partner opposes it.  \nProvided that, without the consent of all the partn ers no act which is \nnot related with the business of a firm shall be performed under the name of \npartnership.  \n(2)  If the partners enter in to an agreement to pe rform all or any act \nof the partnership by all partners or by two or mor e than two partners \njointly and if such partners are unable to perform the assigned task due to a \nreasonable reason, they may authorize to a partner among themselves.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "18", "title": "Entitlement to have access to and to copy of the account and", "content": "books of the firm : Every Partner shall be entitled to have access to the \naccount and books of the firm and if a partner inte nds to get a copy of it the \npartner who holds such book and document shall prep are a copy of original \ndocument and provide to such partner upon putting his/her signature.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "19", "title": "Remuneration and interest : (1) Every partner shall be entitled to", "content": "receive remuneration as specified in the agreement for managing the \nbusiness of the firm and if the partner has investe d additional capital than \nhe/she has agreed to subscribe, under the agreement  he/she shall be entitled \nto receive an interest not exceeding Ten percent.  \n(2) If a partner, knowingly or negligently causes a ny loss or damage, \nhe/she shall be liable to pay back the values or am ount of such loss or \ndamage.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "20", "title": "Profit derived by the partner to be the property of firm : If a partner", "content": "derives any   profit for him/her from any transacti on of the firm, or from the \nuse of the property or business connected with the firm or in the name of \nthe firm he/she shall account for that profit and pay it to the firm.  \nwww.lawcommission.gov.np \n9 \nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "21", "title": "The amount paid by the partners shall be mentioned  in the", "content": "account : The amount paid by the partners pursuant to Secti on 19 and 20, \nshall be clearly mentioned in the profit and loss account of the fiscal year of \nthe firm.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "22", "title": "Share of profit and loss : (1) In the course of sharing the profit and loss", "content": "between/among partners it shall be shared in a mann er as referred to in the \nagreement, if any and it shall be shared on the prorata  basis if such \nprovision does not exist in the agreement.   \n(2) Where there is an agreement between/among partn ers in respect \nof interest on the capital subscribed by a partner in the course of promoting \nof the partnership, such an interest shall be paid only out of the profit.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "23", "title": "No entitlement to profit : If a partner fails to pay the capital to be", "content": "subscribed by him/her to the firm, he/she shall not  be entitled to receive \nhis/her profit until he/she pays the said capital.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter– 4", "title": "Chapter– 4", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "24", "title": "Partners are entitled to represent the firm : Every partner may,", "content": "subject to agreement as referred to in Section 17, represent the firm and the \nact of a partner which is done to carry on the busi ness of the firm shall bind \nthe firm. In the course of carrying on the business  of the firm if a partner \ncommits an act of fraud and any other partner bring s the complaint in this \nregard a competent court may exclude such partner to represent the firm.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "25", "title": "An act done by the partner binds the firm : The Partners shall have", "content": "right to impose a restriction in connection with th e representation of a firm \nby an agreement. Notwithstanding anything contained  in such conditional \n(restriction) agreement, if the third party does no t know the matter of such \nwww.lawcommission.gov.np \n10 \nwww.lawcommission.gov.np \nrestriction, an act done by every partner for carry ing out the business of the \nfirm shall bind the firm.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "26", "title": "Liability of a partner :  Every partner shall be liable jointly or personal ly", "content": "with all the other partners for all the acts of the  firm done while he/she was \na partner.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "27", "title": "No new partner shall be liable : (1) A person who is newly introduced", "content": "as a partner into a firm shall not be liable for any act of the firm done before \nhe/she became a partner.  \n(2) A retired partner(who excludes him/herself from  the partnership) \nmay be discharged from any liability to any third p arty for the acts of the \nfirm done before his/her retirement (exclusion) by an agreement concluded \nbetween him/her and such third party and by the con sent of remaining \npartners of the firm.  \n(3) If a third party knows that any partner is goin g for retirement \nfrom the partnership,  the retired partner shall no t be liable to any third \nparty for  the acts done by other partners in the n ame of the firm after \nhis/her retirement.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "28", "title": "Partner may transfer his/her interest : If any partner transfers his/her", "content": "interest in the firm by a sale, mortgage or by any other method to someone \nelse such person may be entitled to claim the profi t or any other amount to \nbe received by the said partner from the business o f partnership within that \nperiod.  \nProvided that,  \n(a) Such person shall not be considered to be a partner  of \nthe firm.  \nwww.lawcommission.gov.np \n11 \nwww.lawcommission.gov.np \n(b) Such person shall not be entitled to access to the \naccount of the firm without the consent of all the \npartners.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -5", "title": "Chapter -5", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "29", "title": "Dissolution of a firm (partnership) : A Firm may be dissolved with the", "content": "consent of all the partners or in accordance with a n agreement concluded \nbetween/among the partners.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "30", "title": "Dissolution by  notice : If a  firm was constituted not for the specific", "content": "term, any partner may, at any time, cause to dissol ve the firm by providing \na notice in writing to all the other partners. Unle ss there is an otherwise \nconsent between/among partners, the firm shall be d eemed to have \ndissolved from the date as mentioned in the notice or, if such a date is not \nmentioned, from the date of the communication (service) of such a notice.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "31", "title": "Firm may be dissolved at any time : Notwithstanding anything", "content": "contained in the agreement between partners, any pa rtner may cause to \ndissolve the firm for specific reasons and particul arly in the following \ncircumstances;   \n(a)  If a partner has become incapable of performin g his/her duties of the \nfirm as referred to in the agreement; or  \n(b)  If any other partner fails to pay the amount t o be  paid to the firm, or \nif he/she transfers his/her/ interest in the firm t o a third party  \nwithout the consent of all the other partners; or  \n(c)  If the interest of any other partner is attach ed ( Bhari Bharau) by the \ncourt; or \nwww.lawcommission.gov.np \n12 \nwww.lawcommission.gov.np \n(d)  If a partner commits an act of fraud or an act  of serious recklessness \nin the business of the firm; or  \n(e)  If a penalty of imprisonment is imposed to any  other partner.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "32", "title": "After the expiry of the term the firm shall, ipso facto , be dissolved :", "content": "Subject to the agreement between the partners a fir m shall , ipso  facto, be \ndissolved if it was constituted for a specific term , by the expiry of the term \nand if constituted to carry out one or more adventu res or undertakings, \nupon the completion thereof.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "33", "title": "Firm shall be dissolved immediately : A firm shall be dissolved", "content": "immediately, upon the death of a partner or upon th e adjudication of a \npartner as an insolvent for being unable to pay back the debt of the creditor.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "34", "title": "Liability to be fulfilled towards  the third part y : In case where", "content": "public notice of dissolution is not given or published, or a third party who is \nrelated to the firm does not know  about such disso lution, all the partners \nshall be liable as such to the third party for any act or activity done by any \nof them in the name of the firm even after the dissolution of the firm \nProvided that, the estate of a deceased partner or an insolvent partner \nshall not be liable for any act of the firm done after his/her death or after the \ndate on which he/she is adjudicated an insolvent, as the case may be.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "35", "title": "Participation through attorney : Subject to Section 32, every partner", "content": "shall be entitled to take part in the process of di ssolution of the firm, by \nhimself/herself or through the attorney.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "36", "title": "Continuing authority of partners even after disso lution : The", "content": "authority of each partner to bind the firm for comp leting the function, as \nmay be required  of dissolution of the firm, the ot her mutual rights and \nobligations of the partners so far as it may be nec essary to wind up the \nwww.lawcommission.gov.np \n13 \nwww.lawcommission.gov.np \naffairs of the firm, the authority to complete tran sactions begun but \nunfinished at the time of dissolution and the autho rity to  determine  mutual \nright and obligation of each partners shall be cont inued even after the \ndissolution of the  firm", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "37", "title": "Mode of settlement of account between partners:  In the course of", "content": "settling the accounts of a firm after dissolution, the following norms shall, \nsubject to an agreement between partners and Section 32, be followed;  \n(a)  To convert the estate of a firm in to monetary  value,  \n(b)  Losses including deficiencies of capital shall  be paid firstly out of \nprofits secondly out of capital if it is not suffic ient and lastly out of \nthe individual assets of every partner.  \n(c)  The assets of the firm including to make up de ficiencies of capital \nshall be applied in the following manner and order;  \n(1)  In paying the debts of the firm to the third p arties; \n(2)   In paying to each partner proportionately ( Damasahi)  what is \ndue to him/her from the firm for the debt as distin guished \nfrom capital ;  \n(3)  In paying to each partner proportionately ( Damasahi)   what is \ndue to him/her on account of capital; and  \n(4)   The residue, if any, shall be divided among t he partners in the \nproportion which they were entitled to share profits.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "38", "title": "The assets of the firm shall not be divided : Despite any agreement", "content": "between partners no assets of the firm shall be div ided between/among the \npartners without paying the debt of the firm.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "39", "title": "Appointment of liquidator : If a partner lodges a complaint with the", "content": "concerned Department along with the evidence statin g that there is \nwww.lawcommission.gov.np \n14 \nwww.lawcommission.gov.np \nunnecessary delay to settle the accounts of a firm,  the concerned \nDepartments may, in order to carry out the task for  dissolution of the firm, \nappoint Liquidator or Liquidators. Liquidator or Li quidators, as the case \nmay be, shall, subject to partnership agreement and  this Act, fulfill the task \nof dissolution and settle the accounts of the firm.  The act or activities of the \nliquidator shall be controlled by the concerned Department.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "40", "title": "Appeal : A partner, who is not satisfied with the decision  made by the", "content": "concerned Department, may file an appeal before Court of Appeal 7 within a \nperiod of Thirty Five days from receiving the notice of such decision.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-6", "title": "Chapter-6", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "41", "title": "Penalty :  The concerned Department may impose following pe nalty in the", "content": "following matters;  \n(a)  If a firm carries on any business without regi stration in \ncontravention of Section 5, every partner shall be liable to a fine not \nexceeding Fifty rupees;  \n(b)  If it appears that false particulars has been provided in the \napplication pursuant to Sections 6 , every partner of the firm shall be \nliable to a fine not exceeding One Hundred Rupees;  \n(c)  A firm which fails to provide the notice pursu ant to Section 10 shall \nbe liable to a fine not exceeding One Hundred Rupees; \n(d)  A firm which contravenes Section 11 every part ner of the firm shall \nbe liable to a fine not exceeding Fifty Rupees; \n                                                             \n7  Amended by Administration of Justice Act, 2048 \nwww.lawcommission.gov.np \n15 \nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "42", "title": "Appeal : An appeal may be filed before Court of Appeal 8 against the", "content": "decision made by the concerned Department pursuant to Clauses of Section \n41.  \n942A.  Power to alter Schedule : Government of Nepal may alter the schedule \nby publishing a Notification in Nepal Gazette.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "43", "title": "To be governed by this Act :  The matters set forth in this Act shall be", "content": "governed by this Act and other matters shall be gov erned by the prevailing \nlaws.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "44", "title": "Power to frame Rules : The Government of Nepal may frame Rules to", "content": "carry out the objectives of this Act.  \n \n   \n \n                                                             \n8  Amended by Administration of Justice of Act, 2048 . \n9  Amended by First Amendment.  \nwww.lawcommission.gov.np \n16 \nwww.lawcommission.gov.np \n10 Schedule - 1 (a)  \nFormat of an application to be submitted to the con cerned Department \nfor the registration of a firm.  \nTo,  \nThe Director-General \nMinistry of Industry/Commerce  \n Department of Industry/Cottage and Rural Industry/Commerce  \nDear sir/madam \n Since we have agreed to constitute a partnership f irm to carry on the \nbusiness as mentioned below, therefore, hereby, sub mit this application along with \nthe instrument of agreement. We hereby request to r egister the following firm as \nmentioned below in our name upon collecting necessa ry government fee. The \ncontents mentioned in this application are true and  correct and if found to be false \nwe shall be liable according to law.                         \nFollowing", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "1", "title": "Amount of share……..", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Three generation name of partners and their", "content": "address……...  \nWitness  \nSignature of the witness stating that  \nthe above mentioned name, surname  \nand address of applicant is true and correct    \nSignature of the Applicant   \n                                                             \n10   Amended by First amendment and subsequently chang ed by a Notification published in Nepal Gazette \nin 2061-4-18 (2 August 2004). \nwww.lawcommission.gov.np \n17 \nwww.lawcommission.gov.np \n11 Schedule - 1(b) \nFormat of the application to be submitted for the r enewal of a firm  \nDate: ..... \n \nTo,  \nThe Director-General \nMinistry of industry/commerce  \n Department of Industry/cottage and small industry/ Commerce Katmandu, Nepal.  \n \n \nDear sir/madam,  \n \n As, this firm has received the certificate of regi stration under \nregistration number .......... from the Department to carry on the business of ....... \nwe, hereby submit this application for the renewal of the certificate. We, hereby \nrequest to renew the certificate.  \n \n \n \nThe signature of the head  \nPartner in the firm \n(Name of firm)  \n                                                             \n11   Amended by First Amendment. \nwww.lawcommission.gov.np \n18 \nwww.lawcommission.gov.np \n12 Schedule -2(a)  \nRegistration fees of the firm  \n  \nTo registration a Partnership Firm, having a Capita l as mentioned \nhereunder, the registration fee shall be as follows:  \n-  A firm having capital up to One Hundred \nThousand Rupees - Six Hundred Rupees.  \n-  A firm having capital more than One \nHundred Thousand Rupees and up to Three \nHundred Thousand Rupees  -Two Thousand Rupees.  \n-  A firm having capital more than Three \nHundred Thousand Rupees and up to Five   \nHundred Thousand Rupees  -Four Thousand Fifty Rupee s.  \n-  A firm having capital more than Five \nHundred Thousand Rupees and up to One \nMillion Rupees  -Seven Thousand Five Hundreds Rupee s.  \n-  A firm having capital more than One \nMillion Rupees and up to Five Million \nRupees  - Ten Thousand Rupees. \n-  A firm having capital more than Five \nMillion Rupees -Fifteen Thousand Rupees \n   \n \n \n \n                                                             \n12   Amended by First Amendment and subsequently chang ed  by a Notification  published in Nepal \nGazette in 2061-4-18 (2 August 2004). \nwww.lawcommission.gov.np \n19 \nwww.lawcommission.gov.np \n13 Schedule -2(b)  \n  Renew fee of a firm  \n-  A firm having capital up to One Hundred \nThousand Rupees  - One Hundred Rupees  \n-  A firm having capital more than One Hundred \nThousand Rupees and up to Three Hundred \nThousand Rupees  - One Hundred Twenty Five Rupees. \n-  A firm having capital more than Three Hundred \nThousand Rupees and up to Five Hundred \nThousand Rupees  -One Hundred Fifty Rupees.  \n-  A firm having capital more than Five Hundred \nThousand Rupees and up to One Million Rupees  -Two Hundred Rupees.                      \n                      \n- A firm having capital more than One Million \nRupees and up to Five Million.  - Two Hundred Fifty  Rupees \n-  A firm having capital above Five Million Rupees -Three hundred Rupees .  \n                                                             \n13   Amended by Partnership (First amendment) Act, 204 4 and subsequently changed by a Notification \npublished in Nepal Gazette in 2061-4-18 (2 August 2004). \n \n \nwww.lawcommission.gov.np \n20 \nwww.lawcommission.gov.np \n14 Schedule - 3(a)  \nFormat of the registration certificate of a firm  \nGovernment of Nepal  \nMinistry of Industry/ commerce  \n Department of Industry/cottage and small \nindustry/ Commerce                                       \nregistration certificate \n  \n  This certificate has been issued pursuant to Part nership Act, 2020 for the \nfirm called.............. Registered in this Depart ment under the registration \nnumber………….  \n-  Name of partners….. \n- Address …. \n- Total capital…  \n- Objectives… \n- Address of the firm … \n-          Date        ............................  \nDirector General  \nNote \n: This certificate shall be renewed within Thirty Fi ve days of the end of fiscal \nyear. No any other acts other than mentioned in the  objectives of the firm \nshall be carried on by the firm. Appear along with this certificate for its \nrenewal. It shall be renewed by the concerned Department  \n \n \n \n \n                                                             \n14   Amended by First Amendment and subsequently chang ed by  a Notification  published in  Nepal \nGazette in 2061-4-18 (2 August 2004) \nwww.lawcommission.gov.np \n21 \nwww.lawcommission.gov.np \nOn the reverse side of Firm Registration Certificate \nRenewed Date Expiry Date of Renewal Signature of Authority \nwho renewed \n   \n \n \n  \nwww.lawcommission.gov.np \n22 \nwww.lawcommission.gov.np \n15 Schedule 3 (b) \n                                                             \n15   Omitted by First Amendment.", "children": []}]}]$CODExb1756b2b5a97$::jsonb) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,"originalTitle"=EXCLUDED."originalTitle","documentType"=EXCLUDED."documentType","yearBs"=EXCLUDED."yearBs","yearAd"=EXCLUDED."yearAd","totalPages"=EXCLUDED."totalPages",nodes=EXCLUDED.nodes;
